INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22TM0RG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has center $(3, -2)$ and passes through the point $(7, -2)$. What is the area of the circle?', NULL, '[{"key":"A","text":"$8\\\\pi$"},{"key":"B","text":"$16\\\\pi$"},{"key":"C","text":"$32\\\\pi$"},{"key":"D","text":"$64\\\\pi$"}]'::jsonb, 'B', NULL, E'The correct answer is B. The radius of the circle is the distance from the center $(3, -2)$ to the point $(7, -2)$. Since both points share the same $y$-coordinate, the distance is $|7 - 3| = 4$. The area of a circle is $A = \\pi r^2 = \\pi(4)^2 = 16\\pi$. Option A ($8\\pi$) results from confusing radius with diameter and using $r = 2$, or computing $2\\pi r$ instead of $\\pi r^2$. Option C ($32\\pi$) comes from an arithmetic error such as doubling the correct area. Option D ($64\\pi$) results from using the diameter $8$ in place of the radius in the area formula, giving $\\pi(8)^2 = 64\\pi$.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);

INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DCX9E2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle is $x^2 + y^2 - 6x + 10y + 18 = 0$. What is the length of the radius of this circle?', NULL, '[{"key":"A","text":"$4$"},{"key":"B","text":"$\\\\sqrt{7}$"},{"key":"C","text":"$\\\\sqrt{34}$"},{"key":"D","text":"$\\\\sqrt{18}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. To find the radius, complete the square for both $x$ and $y$. Group terms: $(x^2 - 6x) + (y^2 + 10y) = -18$. Complete the square: $(x^2 - 6x + 9) + (y^2 + 10y + 25) = -18 + 9 + 25$, which gives $(x - 3)^2 + (y + 5)^2 = 16$. The standard form $(x - h)^2 + (y - k)^2 = r^2$ shows $r^2 = 16$, so $r = 4$. Option B ($\\sqrt{7}$) results from a sign error when adding the completing-the-square constants, such as subtracting $9$ and $25$ instead of adding them. Option C ($\\sqrt{34}$) comes from adding the completing-the-square constants ($9 + 25 = 34$) without subtracting the original constant $18$, treating $r^2 = 9 + 25$. Option D ($\\sqrt{18}$) comes from incorrectly using the constant $18$ from the original equation as $r^2$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);

INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YDHENN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'In the $xy$-plane, a circle has center $(0, 0)$ and radius $5$. The line $y = 3$ intersects the circle at two points. What is the distance between these two points?', NULL, '[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$10$"}]'::jsonb, 'C', NULL, E'The correct answer is C. The circle has equation $x^2 + y^2 = 25$. Substituting $y = 3$ gives $x^2 + 9 = 25$, so $x^2 = 16$ and $x = \\pm 4$. The two intersection points are $(-4, 3)$ and $(4, 3)$. The distance between them is $|4 - (-4)| = 8$. Option A ($3$) results from stopping at the $y$-value rather than finding the horizontal distance between the two points. Option B ($6$) comes from an arithmetic slip such as computing $\\sqrt{25 - 9} = \\sqrt{16} = 4$ but then doubling $3$ instead of $4$. Option D ($10$) results from using the diameter of the circle rather than computing the actual chord length.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
